// ============================================
// VALIDATION INPUT - LLM Summarizer
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required field ---
const text = body.text || ctx.text;
if (!text || typeof text !== 'string' || text.trim().length === 0) {
  errors.push('text requis (chaine non vide)');
}

// --- Context fields for tracing ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Optional parameters ---
const provider = (body.provider || ctx.provider || 'anthropic').toLowerCase();
const format = body.format || ctx.format || null;
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 1024);

// Validate provider
const validProviders = ['anthropic', 'openai', 'mistral'];
if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider} (doit etre: ${validProviders.join(', ')})`);
}

// Validate format if provided
const validFormats = ['bullet-points', 'paragraph', 'executive-summary'];
if (format && !validFormats.includes(format)) {
  errors.push(`format invalide: ${format} (doit etre: ${validFormats.join(', ')})`);
}

// --- API Keys from env or request ---
const anthropicKey = body.anthropic_api_key || body.plugin_context?.api_keys?.anthropic || $env.ANTHROPIC_API_KEY || '';
const openaiKey = body.openai_api_key || body.plugin_context?.api_keys?.openai || $env.OPENAI_API_KEY || '';
const mistralKey = body.mistral_api_key || body.plugin_context?.api_keys?.mistral || $env.MISTRAL_API_KEY || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  text: text.trim(),
  provider: provider,
  format: format,
  max_tokens: maxTokens,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  anthropicKey: anthropicKey,
  openaiKey: openaiKey,
  mistralKey: mistralKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

