={{ (() => {
  const data = $json;
  let prompt = 'Summarize the following text';
  if (data.format) prompt += ` in ${data.format} format`;
  if (data.user_request) prompt += `. User context: ${data.user_request}`;
  prompt += `:\n\n${data.text}`;
  return JSON.stringify({
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: 'You are a professional summarizer. Create clear, concise summaries that capture the main points and key information.' },
      { role: 'user', content: prompt }
    ],
    max_tokens: data.max_tokens || 1024,
    temperature: 0.3
  });
})() }}

