// ============================================
// FORMAT OPENAI RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Handle error response
if (input.error) {
  return {
    success: false,
    error: {
      code: 'LLM_ERROR',
      message: input.error.message || 'OpenAI API error',
      http_status: 500
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'openai',
      model: 'gpt-4o-mini',
      tokens: { input: 0, output: 0 },
      latency_ms: Date.now() - startTime,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  };
}

const summary = input.choices?.[0]?.message?.content || '';
const originalLength = prevData.text.length;
const summaryLength = summary.length;

const _trace = {
  llm_response: summary,
  service_response: input,
  provider: 'openai',
  model: 'gpt-4o-mini',
  tokens: {
    input: input.usage?.prompt_tokens || 0,
    output: input.usage?.completion_tokens || 0
  },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return {
  success: true,
  data: {
    summary: summary,
    original_length: originalLength,
    summary_length: summaryLength
  },
  meta: {
    provider: 'openai',
    model: 'gpt-4o-mini',
    format: prevData.format
  },
  user_id: userId,
  guild_id: guildId,
